#include <string.h>
static bool room(esphome_pb_writer_t*w,size_t n){if(w->failed||n>w->cap-w->len){w->failed=true;return false;}return true;}
static bool rawv(esphome_pb_writer_t*w,uint64_t v){do{if(!room(w,1))return false;uint8_t b=(uint8_t)(v&0x7f);v>>=7;if(v)b|=0x80;w->buf[w->len++]=b;}while(v);return true;}
static bool tag(esphome_pb_writer_t*w,uint32_t f,uint8_t wire){return f&&rawv(w,((uint64_t)f<<3)|wire);}
void esphome_pb_writer_init(esphome_pb_writer_t*w,uint8_t*b,size_t c){*w=(esphome_pb_writer_t){.buf=b,.cap=c};}
bool esphome_pb_put_varint(esphome_pb_writer_t*w,uint32_t f,uint64_t v){return tag(w,f,0)&&rawv(w,v);}
bool esphome_pb_put_fixed32(esphome_pb_writer_t*w,uint32_t f,uint32_t v){if(!tag(w,f,5)||!room(w,4))return false;w->buf[w->len++]=(uint8_t)v;w->buf[w->len++]=(uint8_t)(v>>8);w->buf[w->len++]=(uint8_t)(v>>16);w->buf[w->len++]=(uint8_t)(v>>24);return true;}
bool esphome_pb_put_float(esphome_pb_writer_t*w,uint32_t f,float v){uint32_t x;memcpy(&x,&v,4);return esphome_pb_put_fixed32(w,f,x);}
bool esphome_pb_put_bool(esphome_pb_writer_t*w,uint32_t f,bool v){return esphome_pb_put_varint(w,f,v?1:0);}
bool esphome_pb_put_string(esphome_pb_writer_t*w,uint32_t f,const char*s,size_t max){if(!s)return false;size_t n=strnlen(s,max+1);if(n>max){w->failed=true;return false;}if(!tag(w,f,2)||!rawv(w,n)||!room(w,n))return false;memcpy(w->buf+w->len,s,n);w->len+=n;return true;}
void esphome_pb_reader_init(esphome_pb_reader_t*r,const uint8_t*b,size_t n){*r=(esphome_pb_reader_t){.buf=b,.len=n};}
static bool readv(esphome_pb_reader_t*r,uint64_t*out){uint64_t v=0;unsigned sh=0;for(unsigned i=0;i<10;i++){if(r->pos>=r->len){r->failed=true;return false;}uint8_t b=r->buf[r->pos++];if(sh==63&&(b&0xfe)){r->failed=true;return false;}v|=(uint64_t)(b&0x7f)<<sh;if(!(b&0x80)){*out=v;return true;}sh+=7;}r->failed=true;return false;}
bool esphome_pb_next(esphome_pb_reader_t*r,uint32_t*f,uint8_t*wire,uint64_t*v,const uint8_t**bytes,size_t*bn,uint32_t*fx){if(r->failed||r->pos>=r->len)return false;uint64_t t;if(!readv(r,&t)||(t>>3)==0){r->failed=true;return false;}*f=(uint32_t)(t>>3);*wire=(uint8_t)(t&7);*v=0;*bytes=NULL;*bn=0;*fx=0;switch(*wire){case 0:return readv(r,v);case 1:if(r->len-r->pos<8){r->failed=true;return false;}r->pos+=8;return true;case 2:{uint64_t n;if(!readv(r,&n)||n>r->len-r->pos){r->failed=true;return false;}*bytes=r->buf+r->pos;*bn=(size_t)n;r->pos+=(size_t)n;return true;}case 5:if(r->len-r->pos<4){r->failed=true;return false;}*fx=(uint32_t)r->buf[r->pos]|((uint32_t)r->buf[r->pos+1]<<8)|((uint32_t)r->buf[r->pos+2]<<16)|((uint32_t)r->buf[r->pos+3]<<24);r->pos+=4;return true;default:r->failed=true;return false;}}
void esphome_pb_copy_string(char*d,size_t cap,const uint8_t*s,size_t n){if(!cap)return;size_t k=n<cap-1?n:cap-1;if(k)memcpy(d,s,k);d[k]=0;}
float esphome_pb_fixed32_to_float(uint32_t x){float v;memcpy(&v,&x,4);return v;}
bool esphome_api_codec_hello_request(uint8_t*out,size_t cap,size_t*len){if(!out||!len)return false;esphome_pb_writer_t w;esphome_pb_writer_init(&w,out,cap);esphome_pb_put_string(&w,1,"One-OS",32);esphome_pb_put_varint(&w,2,1);esphome_pb_put_varint(&w,3,15);*len=w.len;return !w.failed;}
bool esphome_api_codec_parse_hello(const uint8_t*b,size_t n,esphome_api_probe_result_t*out){if(!out)return false;esphome_pb_reader_t r;esphome_pb_reader_init(&r,b,n);uint32_t f,fx;uint8_t w;uint64_t v;const uint8_t*p;size_t l;while(esphome_pb_next(&r,&f,&w,&v,&p,&l,&fx)){if(w==0&&f==1)out->api_version_major=(uint32_t)v;else if(w==0&&f==2)out->api_version_minor=(uint32_t)v;else if(w==2&&f==3)esphome_pb_copy_string(out->server_info,sizeof(out->server_info),p,l);else if(w==2&&f==4)esphome_pb_copy_string(out->name,sizeof(out->name),p,l);}return !r.failed;}
bool esphome_api_codec_parse_device_info(const uint8_t*b,size_t n,esphome_api_probe_result_t*out){if(!out)return false;esphome_pb_reader_t r;esphome_pb_reader_init(&r,b,n);uint32_t f,fx;uint8_t w;uint64_t v;const uint8_t*p;size_t l;while(esphome_pb_next(&r,&f,&w,&v,&p,&l,&fx)){if(w==2){switch(f){case 2:esphome_pb_copy_string(out->name,sizeof(out->name),p,l);break;case 3:esphome_pb_copy_string(out->mac_address,sizeof(out->mac_address),p,l);break;case 4:esphome_pb_copy_string(out->esphome_version,sizeof(out->esphome_version),p,l);break;case 5:esphome_pb_copy_string(out->compilation_time,sizeof(out->compilation_time),p,l);break;case 6:esphome_pb_copy_string(out->model,sizeof(out->model),p,l);break;case 8:esphome_pb_copy_string(out->project_name,sizeof(out->project_name),p,l);break;case 9:esphome_pb_copy_string(out->project_version,sizeof(out->project_version),p,l);break;case 12:esphome_pb_copy_string(out->manufacturer,sizeof(out->manufacturer),p,l);break;case 13:esphome_pb_copy_string(out->friendly_name,sizeof(out->friendly_name),p,l);break;}}else if(w==0&&f==19)out->api_encryption_supported=v!=0;}return !r.failed;}
static esphome_api_entity_kind_t ek(uint16_t t){switch(t){case 12:return ESPHOME_API_ENTITY_BINARY_SENSOR;case 15:return ESPHOME_API_ENTITY_LIGHT;case 16:return ESPHOME_API_ENTITY_SENSOR;case 17:return ESPHOME_API_ENTITY_SWITCH;case 18:return ESPHOME_API_ENTITY_TEXT_SENSOR;case 49:return ESPHOME_API_ENTITY_NUMBER;case 52:return ESPHOME_API_ENTITY_SELECT;case 58:return ESPHOME_API_ENTITY_LOCK;case 61:return ESPHOME_API_ENTITY_BUTTON;default:return ESPHOME_API_ENTITY_UNKNOWN;}}
static void packed_modes(esphome_api_entity_t*out,const uint8_t*p,size_t n){esphome_pb_reader_t r={.buf=p,.len=n};while(r.pos<r.len&&!r.failed){uint64_t v;if(!readv(&r,&v))break;if(v<32)out->detail.light.color_modes_mask|=1u<<(uint32_t)v;}}
bool esphome_api_codec_parse_entity(uint16_t t,const uint8_t*b,size_t n,esphome_api_entity_t*out){if(!out)return false;memset(out,0,sizeof(*out));out->kind=ek(t);if(out->kind==ESPHOME_API_ENTITY_UNKNOWN)return false;esphome_pb_reader_t r;esphome_pb_reader_init(&r,b,n);uint32_t f,fx;uint8_t w;uint64_t v;const uint8_t*p;size_t l;while(esphome_pb_next(&r,&f,&w,&v,&p,&l,&fx)){if(w==2&&f==1)esphome_pb_copy_string(out->object_id,sizeof(out->object_id),p,l);else if(w==5&&f==2)out->key=fx;else if(w==2&&f==3)esphome_pb_copy_string(out->name,sizeof(out->name),p,l);switch(t){case 12:if(w==2&&f==5)esphome_pb_copy_string(out->device_class,sizeof(out->device_class),p,l);else if(w==0&&f==6)out->detail.binary_sensor.is_status=v;else if(w==0&&f==7)out->disabled_by_default=v;else if(w==0&&f==9)out->entity_category=(uint32_t)v;else if(w==0&&f==10)out->device_id=(uint32_t)v;break;case 15:if(w==5&&f==9)out->detail.light.min_mireds=esphome_pb_fixed32_to_float(fx);else if(w==5&&f==10)out->detail.light.max_mireds=esphome_pb_fixed32_to_float(fx);else if(w==0&&f==12&&v<32)out->detail.light.color_modes_mask|=1u<<(uint32_t)v;else if(w==2&&f==12)packed_modes(out,p,l);else if(w==0&&f==13)out->disabled_by_default=v;else if(w==0&&f==15)out->entity_category=(uint32_t)v;else if(w==0&&f==16)out->device_id=(uint32_t)v;break;case 16:if(w==2&&f==6)esphome_pb_copy_string(out->unit,sizeof(out->unit),p,l);else if(w==0&&f==7)out->detail.sensor.accuracy_decimals=(int32_t)v;else if(w==2&&f==9)esphome_pb_copy_string(out->device_class,sizeof(out->device_class),p,l);else if(w==0&&f==10)out->detail.sensor.state_class=(uint32_t)v;else if(w==0&&f==12)out->disabled_by_default=v;else if(w==0&&f==13)out->entity_category=(uint32_t)v;else if(w==0&&f==14)out->device_id=(uint32_t)v;break;case 17:if(w==0&&f==6)out->detail.switch_.assumed_state=v;else if(w==0&&f==7)out->disabled_by_default=v;else if(w==0&&f==8)out->entity_category=(uint32_t)v;else if(w==2&&f==9)esphome_pb_copy_string(out->device_class,sizeof(out->device_class),p,l);else if(w==0&&f==10)out->device_id=(uint32_t)v;break;case 18:if(w==0&&f==6)out->disabled_by_default=v;else if(w==0&&f==7)out->entity_category=(uint32_t)v;else if(w==2&&f==8)esphome_pb_copy_string(out->device_class,sizeof(out->device_class),p,l);else if(w==0&&f==9)out->device_id=(uint32_t)v;break;case 49:if(w==5&&f==6)out->detail.number.min_value=esphome_pb_fixed32_to_float(fx);else if(w==5&&f==7)out->detail.number.max_value=esphome_pb_fixed32_to_float(fx);else if(w==5&&f==8)out->detail.number.step=esphome_pb_fixed32_to_float(fx);else if(w==0&&f==9)out->disabled_by_default=v;else if(w==0&&f==10)out->entity_category=(uint32_t)v;else if(w==2&&f==11)esphome_pb_copy_string(out->unit,sizeof(out->unit),p,l);else if(w==0&&f==12)out->detail.number.mode=(uint32_t)v;else if(w==2&&f==13)esphome_pb_copy_string(out->device_class,sizeof(out->device_class),p,l);else if(w==0&&f==14)out->device_id=(uint32_t)v;break;case 52:if(w==2&&f==6&&out->detail.select.option_count<UINT16_MAX)out->detail.select.option_count++;else if(w==0&&f==7)out->disabled_by_default=v;else if(w==0&&f==8)out->entity_category=(uint32_t)v;else if(w==0&&f==9)out->device_id=(uint32_t)v;break;case 58:if(w==0&&f==6)out->disabled_by_default=v;else if(w==0&&f==7)out->entity_category=(uint32_t)v;else if(w==0&&f==8)out->detail.lock.assumed_state=v;else if(w==0&&f==9)out->detail.lock.supports_open=v;else if(w==0&&f==10)out->detail.lock.requires_code=v;else if(w==0&&f==12)out->device_id=(uint32_t)v;break;case 61:if(w==0&&f==6)out->disabled_by_default=v;else if(w==0&&f==7)out->entity_category=(uint32_t)v;else if(w==2&&f==8)esphome_pb_copy_string(out->device_class,sizeof(out->device_class),p,l);else if(w==0&&f==9)out->device_id=(uint32_t)v;break;}}return !r.failed;}
static esphome_api_entity_kind_t sk(uint16_t t){switch(t){case 21:return ESPHOME_API_ENTITY_BINARY_SENSOR;case 24:return ESPHOME_API_ENTITY_LIGHT;case 25:return ESPHOME_API_ENTITY_SENSOR;case 26:return ESPHOME_API_ENTITY_SWITCH;case 27:return ESPHOME_API_ENTITY_TEXT_SENSOR;case 50:return ESPHOME_API_ENTITY_NUMBER;case 53:return ESPHOME_API_ENTITY_SELECT;case 59:return ESPHOME_API_ENTITY_LOCK;default:return ESPHOME_API_ENTITY_UNKNOWN;}}
bool esphome_api_codec_parse_state(uint16_t t,const uint8_t*b,size_t n,esphome_api_state_t*out){if(!out)return false;memset(out,0,sizeof(*out));out->kind=sk(t);if(out->kind==ESPHOME_API_ENTITY_UNKNOWN)return false;esphome_pb_reader_t r;esphome_pb_reader_init(&r,b,n);uint32_t f,fx;uint8_t w;uint64_t v;const uint8_t*p;size_t l;while(esphome_pb_next(&r,&f,&w,&v,&p,&l,&fx)){if(f==1&&w==5)out->key=fx;switch(t){case 21:if(f==2&&w==0)out->value.boolean=v;else if(f==3&&w==0)out->missing=v;else if(f==4&&w==0)out->device_id=(uint32_t)v;break;case 24:if(f==2&&w==0)out->value.light.state=v;else if(f==3&&w==5)out->value.light.brightness=esphome_pb_fixed32_to_float(fx);else if(f==4&&w==5)out->value.light.red=esphome_pb_fixed32_to_float(fx);else if(f==5&&w==5)out->value.light.green=esphome_pb_fixed32_to_float(fx);else if(f==6&&w==5)out->value.light.blue=esphome_pb_fixed32_to_float(fx);else if(f==7&&w==5)out->value.light.white=esphome_pb_fixed32_to_float(fx);else if(f==8&&w==5)out->value.light.color_temperature=esphome_pb_fixed32_to_float(fx);else if(f==11&&w==0)out->value.light.color_mode=(uint32_t)v;else if(f==14&&w==0)out->device_id=(uint32_t)v;break;case 25:case 50:if(f==2&&w==5)out->value.number=esphome_pb_fixed32_to_float(fx);else if(f==3&&w==0)out->missing=v;else if(f==4&&w==0)out->device_id=(uint32_t)v;break;case 26:if(f==2&&w==0)out->value.boolean=v;else if(f==3&&w==0)out->device_id=(uint32_t)v;break;case 27:case 53:if(f==2&&w==2)esphome_pb_copy_string(out->value.text,sizeof(out->value.text),p,l);else if(f==3&&w==0)out->missing=v;else if(f==4&&w==0)out->device_id=(uint32_t)v;break;case 59:if(f==2&&w==0)out->value.enum_value=(uint32_t)v;else if(f==3&&w==0)out->device_id=(uint32_t)v;break;}}return !r.failed;}
bool esphome_api_codec_command(const esphome_api_command_t*c,uint16_t*t,uint8_t*out,size_t cap,size_t*len){if(!c||!t||!out||!len)return false;esphome_pb_writer_t w;esphome_pb_writer_init(&w,out,cap);esphome_pb_put_fixed32(&w,1,c->key);switch(c->kind){case ESPHOME_API_COMMAND_SWITCH:*t=33;esphome_pb_put_bool(&w,2,c->value.switch_.state);if(c->device_id)esphome_pb_put_varint(&w,3,c->device_id);break;case ESPHOME_API_COMMAND_LIGHT:*t=32;if(c->value.light.has_state){esphome_pb_put_bool(&w,2,true);esphome_pb_put_bool(&w,3,c->value.light.state);}if(c->value.light.has_brightness){esphome_pb_put_bool(&w,4,true);esphome_pb_put_float(&w,5,c->value.light.brightness);}if(c->device_id)esphome_pb_put_varint(&w,28,c->device_id);break;case ESPHOME_API_COMMAND_BUTTON:*t=62;if(c->device_id)esphome_pb_put_varint(&w,2,c->device_id);break;case ESPHOME_API_COMMAND_NUMBER:*t=51;esphome_pb_put_float(&w,2,c->value.number.state);if(c->device_id)esphome_pb_put_varint(&w,3,c->device_id);break;case ESPHOME_API_COMMAND_SELECT:*t=54;if(!c->value.select.state)return false;esphome_pb_put_string(&w,2,c->value.select.state,ESPHOME_API_MAX_STATE_TEXT_LEN);if(c->device_id)esphome_pb_put_varint(&w,3,c->device_id);break;case ESPHOME_API_COMMAND_LOCK:*t=60;if(c->value.lock.command>2)return false;esphome_pb_put_varint(&w,2,c->value.lock.command);if(c->value.lock.code){esphome_pb_put_bool(&w,3,true);esphome_pb_put_string(&w,4,c->value.lock.code,32);}if(c->device_id)esphome_pb_put_varint(&w,5,c->device_id);break;default:return false;}*len=w.len;return !w.failed;}
